using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public class OutboxMessage
{
    public Guid Id { get; set; } = Guid.NewGuid();
    public string EventType { get; set; } = "";
    public string Payload { get; set; } = "";
    public bool IsPublished { get; set; }
}

public class LocalDatabaseContext
{
    public List<string> Orders { get; } = new();
    public List<OutboxMessage> Outbox { get; } = new();

    public void CommitTransaction(string orderData, string eventPayload)
    {
        Orders.Add(orderData);
        Outbox.Add(new OutboxMessage
        {
            EventType = "OrderCreated",
            Payload = eventPayload,
            IsPublished = false
        });

        Console.WriteLine("[Database] Transaksi ACID lokal berhasil di-commit (Order + Outbox tersimpan serentak).");
    }
}

public class OutboxPublisher
{
    public async Task PublishPendingMessagesAsync(LocalDatabaseContext db)
    {
        var pending = db.Outbox.Where(m => !m.IsPublished).ToList();
        foreach (var msg in pending)
        {
            Console.WriteLine($"[BROKER PUBLISH] Menerbitkan {msg.EventType}: {msg.Payload}");
            await Task.Delay(10);
            msg.IsPublished = true;
        }

        Console.WriteLine($"[Outbox Worker] Berhasil menerbitkan {pending.Count} pesan.");
    }
}

public class Program
{
    public static async Task Main()
    {
        var db = new LocalDatabaseContext();
        var publisher = new OutboxPublisher();

        db.CommitTransaction("Order #9901 - Total Rp 500.000", "{\"OrderId\": 9901, \"Amount\": 500000}");

        Console.WriteLine("\n--- Menjalankan Outbox Publisher Worker ---");
        await publisher.PublishPendingMessagesAsync(db);
    }
}
